### C++ 

```cpp
#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

// 快速幂
long long modpow(long long a, long long e) {
	long long r = 1 % MOD;
	a %= MOD;
	while (e > 0) {
		if (e & 1) r = (r * a) % MOD;
		a = (a * a) % MOD;
		e >>= 1;
	}
	return r;
}

// 组合数预处理
int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int n;
	if (!(cin >> n)) return 0;

	// 预处理 factorial 与 invfactorial
	vector<long long> fact(n + 1), invfact(n + 1);
	fact[0] = 1;
	for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
	invfact[n] = modpow(fact[n], MOD - 2);
	for (int i = n; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

	auto C = [&](int N, int K) -> long long {
		if (K < 0 || K > N) return 0;
		return fact[N] * invfact[K] % MOD * invfact[N - K] % MOD;
	};

	// 计算 S = sum_{k=0..n} C(n,k)^2 * inv2^k
	const long long inv2 = (MOD + 1) / 2; // 499122177
	long long S = 0;
	long long cur = 1; // inv2^0
	for (int k = 0; k <= n; ++k) {
		long long comb = C(n, k);
		long long term = comb * comb % MOD * cur % MOD;
		S += term;
		if (S >= MOD) S -= MOD;
		cur = cur * inv2 % MOD;
	}

	// 2^(n^2)
	long long pow2 = modpow(2, 1LL * n * n);

	long long ans = pow2 * S % MOD;
	cout << ans << "\n";
	return 0;
}
```

