def modpow(a, e, mod=MOD):
    """快速幂取模"""
    r = 1
    a %= mod
    while e > 0:
        if e & 1:
            r = (r * a) % mod
        a = (a * a) % mod
        e >>= 1
    return r

def main():
    data = sys.stdin.read().strip().split()
    n = int(data[0])

    # 预处理阶乘和阶乘的逆元
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (n + 1)
    inv_fact[n] = modpow(fact[n], MOD - 2)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def C(N, K):
        """组合数 C(N, K) % MOD"""
        if K < 0 or K > N:
            return 0
        return fact[N] * inv_fact[K] % MOD * inv_fact[N - K] % MOD

    inv2 = (MOD + 1) // 2          # 2 在模 MOD 下的逆元，即 499122177
