    cur = 1                        # cur = (1/2)^k，初始为 (1/2)^0 = 1
    for k in range(n + 1):
        comb = C(n, k)
        term = comb * comb % MOD * cur % MOD
        S = (S + term) % MOD
        cur = cur * inv2 % MOD

    pow2 = modpow(2, n * n)       # 2^{n^2}
    ans = pow2 * S % MOD
    print(ans)

if __name__ == "__main__":
    main()
